#include "dispatch_table.h"   // AB_DISPATCH_BUILTIN_TABLES[], generated by scripts/ingest_calibration.py

static char trans_class(char t) {
    return t == 'N' || t == 'n' ? 'N' : 'T';
}

bool ab_dispatch_row_covers(const ab_dispatch_row_t *row, char routine,
                            char transA, char transB, int M, int N, int K) {
    return row->routine == routine && row->ta == trans_class(transA) &&
           row->tb == trans_class(transB) && M >= row->m && N >= row->n && K >= row->k;
}

bool ab_dispatch_gpu(const ab_dispatch_config_t *c, char routine,
                     char transA, char transB, int M, int N, int K) {
    if (c->mode == AB_DISPATCH_CPU) return false;
    // Dims below the floor are never profitable (threadgroups underutilized).
    if (M <= c->min_dim || N <= c->min_dim || K <= c->min_dim) return false;
    if (c->mode == AB_DISPATCH_GPU) return true;

    uint64_t crossover = routine == 'd' && c->crossover_flops_real
                       ? c->crossover_flops_real : c->crossover_flops;
    if (crossover)   // in double: M*N*K can exceed 2^64
        return (routine == 'z' ? 8.0 : 2.0) * M * N * K >= (double)crossover;

    for (int i = 0; i < c->nrows; i++)
        if (ab_dispatch_row_covers(&c->rows[i], routine, transA, transB, M, N, K))
            return true;
    return false;
}

// =============================================================================
// Table files
// =============================================================================

static bool parse_trans(const char *tok, char *out) {
    if (strlen(tok) != 1 || !strchr("NTCntc", tok[0])) return false;
    *out = trans_class(tok[0]);
    return true;
}

static bool parse_min(const char *tok, int *out) {
    char *end;
    errno = 0;
    long v = strtol(tok, &end, 10);
    if (errno || *end || end == tok || v < 0 || v > INT_MAX) return false;
    *out = (int)v;
    return true;
}

int ab_dispatch_parse_row(const char *line, ab_dispatch_row_t *row) {
    char buf[256], *tok[6], *save = NULL;
    int n = 0;
    snprintf(buf, sizeof buf, "%s", line);
    buf[strcspn(buf, "#\r\n")] = '\0';
    for (char *t = strtok_r(buf, " \t", &save); t; t = strtok_r(NULL, " \t", &save)) {
        if (n == 6) return -1;
        tok[n++] = t;
    }
    if (n == 0) return 0;
    if (n != 6) return -1;

    ab_dispatch_row_t r;
    if (!strcasecmp(tok[0], "dgemm")) r.routine = 'd';
    else if (!strcasecmp(tok[0], "zgemm")) r.routine = 'z';
    else return -1;
    if (!parse_trans(tok[1], &r.ta) || !parse_trans(tok[2], &r.tb) ||
        !parse_min(tok[3], &r.m) || !parse_min(tok[4], &r.n) || !parse_min(tok[5], &r.k))
        return -1;
    *row = r;
    return 1;
}

// Copies s without leading or trailing blanks into out.
static void trimmed(const char *s, size_t n, char *out, size_t len) {
    while (n && isspace((unsigned char)*s)) { s++; n--; }
    while (n && isspace((unsigned char)s[n - 1])) n--;
    if (n >= len) n = len - 1;
    memcpy(out, s, n);
    out[n] = '\0';
}

int ab_dispatch_parse_header(const char *line, char *key, size_t key_len,
                             char *value, size_t value_len) {
    const char *p = line + strspn(line, " \t");
    if (*p != '#') return 0;
    p++;
    p += strspn(p, " \t");
    const char *colon = strchr(p, ':');
    if (!colon || colon == p) return 0;
    // A key is one lowercase word (letters, digits, '_'); "# Machine:  ..."
    // and the other prose lines of a table header are not keys.
    for (const char *q = p; q < colon; q++)
        if (!(islower((unsigned char)*q) || isdigit((unsigned char)*q) || *q == '_')) return 0;
    trimmed(p, (size_t)(colon - p), key, key_len);
    trimmed(colon + 1, strcspn(colon + 1, "#\r\n"), value, value_len);   // a trailing "# note" is not the value
    return 1;
}

bool ab_dispatch_load_table(ab_dispatch_config_t *c, const char *path,
                            char *err, size_t err_len) {
    FILE *f = fopen(path, "r");
    if (!f) {
        snprintf(err, err_len, "%s", strerror(errno));
        return false;
    }
    ab_dispatch_row_t rows[AB_DISPATCH_MAX_ROWS];
    char line[256], chip[AB_DISPATCH_CHIP_LEN] = "", key[32], value[AB_DISPATCH_CHIP_LEN];
    int nrows = 0, lineno = 0, cores = 0;
    const char *why = NULL;
    while (!why && fgets(line, sizeof line, f)) {
        lineno++;
        // A line longer than the buffer is allowed only as a comment.
        bool whole = strchr(line, '\n') || feof(f);
        bool comment = line[strspn(line, " \t")] == '#';
        for (int ch = 0; !whole && ch != '\n' && ch != EOF; ) ch = fgetc(f);
        if (comment && ab_dispatch_parse_header(line, key, sizeof key, value, sizeof value)) {
            if (!strcmp(key, "chip")) snprintf(chip, sizeof chip, "%s", value);
            else if (!strcmp(key, "gpu_cores")) cores = atoi(value) > 0 ? atoi(value) : 0;
            continue;
        }
        ab_dispatch_row_t r;
        int got = whole || comment ? ab_dispatch_parse_row(line, &r) : -1;
        if (got < 0)
            why = "expected '<dgemm|zgemm> <N|T|C> <N|T|C> <min_M> <min_N> <min_K>'";
        else if (got && nrows == AB_DISPATCH_MAX_ROWS)
            why = "too many rows";
        else if (got)
            rows[nrows++] = r;
    }
    if (!why && ferror(f)) why = "read error";
    fclose(f);
    if (why) {
        snprintf(err, err_len, "line %d: %s", lineno, why);
        return false;
    }
    memcpy(c->rows, rows, (size_t)nrows * sizeof rows[0]);
    c->nrows = nrows;
    snprintf(c->table_chip, sizeof c->table_chip, "%s", chip);
    c->table_gpu_cores = cores;
    return true;
}

// =============================================================================
// Chip identity and the built-in table for it
// =============================================================================

const ab_dispatch_table_t *ab_dispatch_select_table(const ab_dispatch_table_t *tables,
                                                    const char *chip, int gpu_cores) {
    if (!chip || !*chip) return NULL;
    const ab_dispatch_table_t *exact = NULL, *any_cores = NULL, *only = NULL;
    int same_chip = 0;
    for (const ab_dispatch_table_t *t = tables; t->chip; t++) {
        if (strcasecmp(t->chip, chip)) continue;
        same_chip++;
        only = t;
        if (gpu_cores > 0 && t->gpu_cores == gpu_cores) exact = t;
        if (t->gpu_cores == 0 && !any_cores) any_cores = t;
    }
    if (exact) return exact;
    if (any_cores) return any_cores;
    if (gpu_cores <= 0 && same_chip == 1) return only;
    return NULL;
}

const ab_dispatch_table_t *ab_dispatch_builtin_table(const char *chip, int gpu_cores) {
    return ab_dispatch_select_table(AB_DISPATCH_BUILTIN_TABLES, chip, gpu_cores);
}

// gpu-core-count of the first AGXAccelerator entry, as `ioreg -rc
// AGXAccelerator -d1` lists it; 0 when there is none (a CI runner without a
// GPU) or the property is missing.
static int ioregistry_gpu_cores(void) {
    io_iterator_t it = IO_OBJECT_NULL;
    if (IOServiceGetMatchingServices(kIOMainPortDefault, IOServiceMatching("AGXAccelerator"), &it) !=
        KERN_SUCCESS)
        return 0;
    int cores = 0;
    for (io_object_t s; !cores && (s = IOIteratorNext(it)); IOObjectRelease(s)) {
        CFTypeRef v = IORegistryEntryCreateCFProperty(s, CFSTR("gpu-core-count"), kCFAllocatorDefault, 0);
        if (!v) continue;
        if (CFGetTypeID(v) == CFNumberGetTypeID() && !CFNumberGetValue(v, kCFNumberIntType, &cores))
            cores = 0;
        CFRelease(v);
    }
    IOObjectRelease(it);
    return cores > 0 ? cores : 0;
}

void ab_dispatch_chip_slug(const char *chip, int gpu_cores, char *out, size_t len) {
    const char *s = chip ? chip : "";
    if (!strncasecmp(s, "Apple", 5)) s += 5;
    size_t n = 0;
    bool dash = true;                       // no leading dash
    for (; *s && n + 1 < len; s++) {
        if (isalnum((unsigned char)*s)) { out[n++] = *s; dash = false; }
        else if (!dash) { out[n++] = '-'; dash = true; }
    }
    while (n && out[n - 1] == '-') n--;
    out[n] = '\0';
    if (!n) snprintf(out, len, "unknown");
    else if (gpu_cores > 0) snprintf(out + n, len - n, "-%dc", gpu_cores);
}

void ab_dispatch_host_chip(char *chip, size_t len, int *gpu_cores) {
    const char *env = getenv("AB_CHIP");
    if (env && *env) {
        trimmed(env, strlen(env), chip, len);
    } else {
        size_t n = len;
        if (sysctlbyname("machdep.cpu.brand_string", chip, &n, NULL, 0) != 0 || n == 0) chip[0] = '\0';
        chip[len - 1] = '\0';
    }
    env = getenv("AB_GPU_CORES");
    if (env && *env) {
        int v = atoi(env);
        *gpu_cores = v > 0 ? v : 0;
    } else {
        *gpu_cores = ioregistry_gpu_cores();
    }
}

// =============================================================================
// Process configuration
// =============================================================================

// "38 GPU cores", or "an unstated GPU core count" for 0, for the notes below.
static const char *cores_text(int n, char *buf, size_t len) {
    if (n > 0) snprintf(buf, len, "%d GPU cores", n);
    else snprintf(buf, len, "an unstated GPU core count");
    return buf;
}

static uint64_t env_flops(const char *name) {
    const char *s = getenv(name);
    return s && *s ? strtoull(s, NULL, 10) : 0;
}

void ab_dispatch_config_from_env(ab_dispatch_config_t *c) {
    memset(c, 0, sizeof *c);
    const char *mode = getenv("AB_MODE");
    c->mode = mode && (mode[0] == 'c' || mode[0] == 'C') ? AB_DISPATCH_CPU
            : mode && (mode[0] == 'g' || mode[0] == 'G') ? AB_DISPATCH_GPU
            : AB_DISPATCH_AUTO;

    const char *min_dim = getenv("AB_MIN_GPU_DIM");
    c->min_dim = min_dim && *min_dim ? atoi(min_dim) : AB_DISPATCH_DEFAULT_MIN_DIM;
    if (c->min_dim < 0) c->min_dim = AB_DISPATCH_DEFAULT_MIN_DIM;

    c->crossover_flops = env_flops("AB_CROSSOVER_FLOPS");
    c->crossover_flops_real = env_flops("AB_CROSSOVER_FLOPS_REAL");

    // The built-in table for this chip, if it was calibrated.
    ab_dispatch_host_chip(c->chip, sizeof c->chip, &c->gpu_cores);
    const ab_dispatch_table_t *t = ab_dispatch_builtin_table(c->chip, c->gpu_cores);
    if (t) {
        for (const ab_dispatch_row_t *r = t->rows; r->routine && c->nrows < AB_DISPATCH_MAX_ROWS; r++)
            c->rows[c->nrows++] = *r;
        snprintf(c->table_chip, sizeof c->table_chip, "%s", t->chip);
        c->table_gpu_cores = t->gpu_cores;
        char slug[AB_DISPATCH_CHIP_LEN];
        ab_dispatch_chip_slug(t->chip, t->gpu_cores, slug, sizeof slug);
        snprintf(c->table, sizeof c->table, "builtin:%s", slug);
    } else {
        snprintf(c->table, sizeof c->table, "none:%s", c->chip[0] ? "uncalibrated-chip" : "unknown-chip");
    }

    const char *table = getenv("AB_DISPATCH_TABLE");
    char err[160];
    if (table && *table) {
        if (!ab_dispatch_load_table(c, table, err, sizeof err)) {
            fprintf(stderr, "apple-bottom: AB_DISPATCH_TABLE=%s: %s; keeping %s\n", table, err, c->table);
        } else {
            snprintf(c->table, sizeof c->table, "file:%s", table);
            bool other_chip = c->table_chip[0] && c->chip[0] && strcasecmp(c->table_chip, c->chip);
            bool other_cores = c->table_gpu_cores && c->gpu_cores && c->table_gpu_cores != c->gpu_cores;
            if (other_chip || other_cores) {
                char tc[40], hc[40];
                fprintf(stderr, "apple-bottom: AB_DISPATCH_TABLE=%s was calibrated on %s with %s; this machine "
                                "is %s with %s; using it anyway\n",
                        table, c->table_chip, cores_text(c->table_gpu_cores, tc, sizeof tc),
                        c->chip[0] ? c->chip : "an unknown chip", cores_text(c->gpu_cores, hc, sizeof hc));
            }
        }
    }
}

static ab_dispatch_config_t g_config;
static pthread_once_t g_config_once = PTHREAD_ONCE_INIT;

static void load_config(void) { ab_dispatch_config_from_env(&g_config); }

const ab_dispatch_config_t *ab_dispatch_process_config(void) {
    pthread_once(&g_config_once, load_config);
    return &g_config;
}

bool ab_dispatch_route_gpu(char routine, char transA, char transB, int M, int N, int K) {
    return ab_dispatch_gpu(ab_dispatch_process_config(), routine, transA, transB, M, N, K);
}
